--- a/Source/FPSGAME/WorldGeneration/TemperateVegetationPlacement.cpp
+++ b/Source/FPSGAME/WorldGeneration/TemperateVegetationPlacement.cpp
@@ -1,6 +1,9 @@
+#include "TemperateHillsStreamingPrivate.h"
 #include "TemperateVegetationPlacement.h"
 #include "EastRiverRoad.h"
 #include "TemperateHillsWorld.h"
+#include "ForestVillageMap.h"
+#include "ForestVillageRegion.h"
 #include "TemperateVillagePlanting.h"
 #include "Engine/StaticMesh.h"
 #include "Engine/SkeletalMesh.h"
@@ -235,7 +238,12 @@
     {
         const FVector2D Delta=Direction*RootRadius;
         const double X=Origin.X+Root.X+Delta.X,Y=Origin.Y+Root.Y+Delta.Y;
-        if(FMath::Abs(X)>Half||FMath::Abs(Y)>Half)return false;
+        if(IsForestVillage())
+        {
+            if(!ForestVillageMap::Bounds().IsInside(FVector2D(X,Y)) || !Streaming || !Streaming->ForestRegion.IsValid()
+                || Streaming->ForestRegion->MapRoadWeight(X,Y)>.45)return false;
+        }
+        else if(FMath::Abs(X)>Half||FMath::Abs(Y)>Half)return false;
         const auto River=RiverPlan?RiverPlan->Sample(X,Y):TemperateRiver::FSample();
         // Emergent reeds and bank cover keep their existing wet-edge habitat;
         // the abstract dry trail must not erase the planted water margin.
@@ -245,7 +253,7 @@
             const auto Road=EastRiverRoad::Sample(X,Y);
             if(Road.Distance<Road.Width+40.)return false;
         }
-        else if(!WetEdge&&PathDistance(X,Y)<(Woody(Kind)||Kind==EKind::Tree?350:210))return false;
+        else if(!IsForestVillage()&&!WetEdge&&PathDistance(X,Y)<(Woody(Kind)||Kind==EKind::Tree?350:210))return false;
         const double Z=Height(X,Y);
         // Newly selected pools share this same plan with water rendering and
         // contacts. Mature roots/terrestrial plants never emerge in a pool.
